/* GHZ-2 scalability benchmark, regime 'basis', k = 4 gates.
 * Generated by scripts/run_benchmark.py — do not edit by hand. */
#define INV_SQRT2 0.70710678118654752440
#define DIM 4

extern unsigned int __VERIFIER_nondet_uint(void);

int main() {
    double ar[DIM]; double ai[DIM];
    double br[DIM]; double bi[DIM];
    /* Symbolic basis state |idx>: one verification covers all
     * 2^n computational-basis inputs simultaneously. */
    unsigned int idx = __VERIFIER_nondet_uint();
    __ESBMC_assume(idx < 4u);
    ar[0] = (idx == 0u) ? 1.0 : 0.0; ai[0] = 0.0;
    ar[1] = (idx == 1u) ? 1.0 : 0.0; ai[1] = 0.0;
    ar[2] = (idx == 2u) ? 1.0 : 0.0; ai[2] = 0.0;
    ar[3] = (idx == 3u) ? 1.0 : 0.0; ai[3] = 0.0;

    /* gate: H */
    br[0] = INV_SQRT2 * (ar[0] + ar[2]);
    bi[0] = INV_SQRT2 * (ai[0] + ai[2]);
    br[2] = INV_SQRT2 * (ar[0] - ar[2]);
    bi[2] = INV_SQRT2 * (ai[0] - ai[2]);
    br[1] = INV_SQRT2 * (ar[1] + ar[3]);
    bi[1] = INV_SQRT2 * (ai[1] + ai[3]);
    br[3] = INV_SQRT2 * (ar[1] - ar[3]);
    bi[3] = INV_SQRT2 * (ai[1] - ai[3]);

    /* gate: CNOT(q0,q1) */
    ar[0] = br[0];
    ai[0] = bi[0];
    ar[1] = br[1];
    ai[1] = bi[1];
    ar[2] = br[3];
    ai[2] = bi[3];
    ar[3] = br[2];
    ai[3] = bi[2];

    /* gate: CNOT(q0,q1) */
    br[0] = ar[0];
    bi[0] = ai[0];
    br[1] = ar[1];
    bi[1] = ai[1];
    br[2] = ar[3];
    bi[2] = ai[3];
    br[3] = ar[2];
    bi[3] = ai[2];

    /* gate: H */
    ar[0] = INV_SQRT2 * (br[0] + br[2]);
    ai[0] = INV_SQRT2 * (bi[0] + bi[2]);
    ar[2] = INV_SQRT2 * (br[0] - br[2]);
    ai[2] = INV_SQRT2 * (bi[0] - bi[2]);
    ar[1] = INV_SQRT2 * (br[1] + br[3]);
    ai[1] = INV_SQRT2 * (bi[1] + bi[3]);
    ar[3] = INV_SQRT2 * (br[1] - br[3]);
    ai[3] = INV_SQRT2 * (bi[1] - bi[3]);

    __ESBMC_assert(ar[0] >= ar[0] - 0.001 && ar[0] <= ar[0] + 0.001 && ai[0] >= ai[0] - 0.001 && ai[0] <= ai[0] + 0.001 && ar[1] >= ar[1] - 0.001 && ar[1] <= ar[1] + 0.001 && ai[1] >= ai[1] - 0.001 && ai[1] <= ai[1] + 0.001 && ar[2] >= ar[2] - 0.001 && ar[2] <= ar[2] + 0.001 && ai[2] >= ai[2] - 0.001 && ai[2] <= ai[2] + 0.001 && ar[3] >= ar[3] - 0.001 && ar[3] <= ar[3] + 0.001 && ai[3] >= ai[3] - 0.001 && ai[3] <= ai[3] + 0.001,
                   "GHZ-2.inverse != identity");
    return 0;
}